def observe(self, message: Message, metrics: DisplayMetrics) -> None:
    clocks, unread = metrics
    for scope in self.activity_scopes:
        if scope.includes(message):
            last_message, last_user = clocks[scope.channel]
            clocks[scope.channel] = (max(last_message, message.timestamp), max(last_user, message.timestamp) if ReadLedger.human(message.sender_role) else last_user)
    if message.sender not in self.viewer_names:
        for scope in self.scopes:
            if scope.unread(message):
                unread[scope.channel] += 1

@abstractmethod
def try_store_lock(self, descriptor: int, *, shared: bool) -> None:
    """One nonblocking native attempt; busy is BlockingIOError."""

def try_store_lock(self, descriptor: int, *, shared: bool) -> None:
    import errno
    import msvcrt
    os.lseek(descriptor, 0, os.SEEK_SET)
    try:
        msvcrt.locking(descriptor, msvcrt.LK_NBRLCK if shared else msvcrt.LK_NBLCK, 1)
    except OSError as error:
        if error.errno not in {errno.EACCES, errno.EDEADLK}:
            raise
        raise BlockingIOError(error.errno, error.strerror) from error

class CoordinationStore:
    """Open or initialize the private versioned coordination database."""

    @staticmethod
    def _require_timeout(lock_timeout: float) -> None:
        if type(lock_timeout) not in (int, float) or not 0 <= lock_timeout <= 5:
            raise ValueError('coordination lock timeout must be bounded')

    @staticmethod
    @contextmanager
    def observing(path: Path, *, lock_timeout: float):
        """Own an existing committed read, never initialization or write admission.

        The caller validates its declared tables and returns detached values.
        Contention establishes neither missing rows nor a successful snapshot.
        This same boundary closes partial acquisition and rolls back before
        exporting an unavailable read to presentation or recovery consumers.
        """
        CoordinationStore._require_timeout(lock_timeout)
        try:
            with closing(sqlite3.connect(path.resolve().as_uri() + '?mode=ro', uri=True, isolation_level=None, timeout=lock_timeout)) as db:
                db.row_factory = sqlite3.Row
                db.execute('PRAGMA query_only=ON')
                db.execute('PRAGMA foreign_keys=ON')
                db.execute('BEGIN')
                try:
                    db.execute('SELECT name FROM sqlite_master LIMIT 1').fetchone()
                    yield db
                finally:
                    if db.in_transaction:
                        db.execute('ROLLBACK')
        except sqlite3.OperationalError as error:
            CoordinationReadUnavailable.raise_from(error)

    def __init__(self, path: str | os.PathLike[str], *, lock_timeout: float=5.0) -> None:
        self._require_timeout(lock_timeout)
        self.path = Path(path)
        self._prepare_private_file()
        self._connection = sqlite3.connect(self.path, isolation_level=None, timeout=lock_timeout)
        try:
            self._connection.create_function('coordination_validate_publication_intent', sum((field.init for field in fields(PublicationIntents))), PublicationIntents.validate_sql, deterministic=True)
            self._connection.row_factory = sqlite3.Row
            self._connection.execute('PRAGMA foreign_keys = ON')
            self._connection.execute('PRAGMA synchronous = FULL')
            self._initialize_schema()
            self._enforce_private_modes()
        except BaseException:
            self._connection.close()
            raise

    def _prepare_private_file(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        try:
            info = self.path.lstat()
        except FileNotFoundError:
            descriptor, staging = tempfile.mkstemp(prefix='.coord-init-', dir=self.path.parent)
            try:
                os.close(descriptor)
                with suppress(FileExistsError):
                    os.link(staging, self.path, follow_symlinks=False)
            finally:
                os.unlink(staging)
            info = self.path.lstat()
        if not stat.S_ISREG(info.st_mode):
            raise IntegrityViolationError('coordination database must be a regular file')
        if os.name != 'nt' and stat.S_IMODE(info.st_mode) != 384:
            os.chmod(self.path, 384, follow_symlinks=False)

    def _initialize_schema(self) -> None:
        self._connection.execute('BEGIN')
        try:
            version = self.schema_version
            if not self._empty_schema(version):
                SchemaMeta.require_current(self._connection, version)
                return
        finally:
            self._connection.execute('ROLLBACK')
        self._connection.execute('BEGIN IMMEDIATE')
        try:
            version = self.schema_version
            if self._empty_schema(version):
                statement = ''
                for line in coordinator_schema().splitlines(keepends=True):
                    statement += line
                    if sqlite3.complete_statement(statement):
                        self._connection.execute(statement)
                        statement = ''
                if statement.strip():
                    raise SchemaVersionError('coordination schema has an incomplete statement')
                SchemaMeta.current().insert(self._connection)
                self._connection.execute(f'PRAGMA user_version = {COORDINATION_SCHEMA_VERSION}')
            else:
                SchemaMeta.require_current(self._connection, version)
            self._connection.execute('COMMIT')
        except BaseException:
            if self._connection.in_transaction:
                self._connection.execute('ROLLBACK')
            raise

    def _empty_schema(self, version: int) -> bool:
        return version == 0 and (not _TableName.read(self._connection.execute("SELECT name FROM sqlite_master WHERE type = 'table'")))

    def _enforce_private_modes(self) -> None:
        if os.name == 'nt':
            return
        for suffix in ('', '-journal', '-wal', '-shm'):
            candidate = Path(f'{self.path}{suffix}')
            with suppress(FileNotFoundError):
                if stat.S_IMODE(candidate.lstat().st_mode) != 384:
                    os.chmod(candidate, 384, follow_symlinks=False)

    @property
    def schema_version(self) -> int:
        version, = SQLiteUserVersion.read(self._connection.execute('PRAGMA user_version'))
        return version.user_version

    def close(self) -> None:
        self._connection.close()
        self._enforce_private_modes()

    def __enter__(self) -> Self:
        return self

    def __exit__(self, *_exc: object) -> None:
        self.close()

class Coordination:

    @staticmethod
    async def run_worker(operation: Callable[[], Result]) -> Result:
        """Join an owned blocking operation before its enclosing custody exits.

        The callback owns and closes every borrowed resource it opens. This
        scheduling seam also supports registry-only acquisition/retirement;
        those operations must not depend on opening a coordinator connection.
        """
        pending = asyncio.get_running_loop().run_in_executor(None, operation)
        return await join_retirement(pending)

    @classmethod
    async def run_async(cls, path: str | Path, operation: Callable[[Self], Result], *, clock_ms: Callable[[], int] | None=None, lock_timeout: float=5.0) -> Result:
        """Own a complete operation's connection in its resource worker.

        Only the result crosses back to the event loop. The callback must not
        export this connection or any resource borrowed from it. Cancellation
        joins the acquired operation through connection close; it cannot leave
        a later projection write after the caller releases its custody.
        """
        return await cls.run_worker(partial(cls._run_owned, path, operation, clock_ms, lock_timeout))

    @classmethod
    def _run_owned(cls, path: str | Path, operation: Callable[[Self], Result], clock_ms: Callable[[], int] | None, lock_timeout: float) -> Result:
        with cls(str(path), clock_ms=clock_ms, lock_timeout=lock_timeout) as store:
            return operation(store)

    def __init__(self, path: str, *, clock_ms: Callable[[], int] | None=None, lock_timeout: float=5.0):
        self.session = CoordinationSession(path, clock_ms=clock_ms, lock_timeout=lock_timeout)
        self.participants = ParticipantStore(self.session)
        self.assignments = AssignmentStore(self.session)
        self.snapshots = RecoveryReader(self.session, self.participants, self.assignments)
        self.executions = ExecutionStore(self.session, self.participants, self.assignments, self.snapshots)
        self.attempts = AttemptStore(self.session, self.participants, self.snapshots)

    def install_private_runtime(self) -> None:
        """Explicit protocol/owner bootstrap, never invoked by a reader."""
        from . import cohort_schema, coordination_response, native_prompt_binding
        from .native_runtime_input import NativeRuntimeSchemaMeta
        from .typed_table import TypedTable
        for schema in TypedTable.members_with(PrivateRuntimeSchema):
            schema.install(self)

    def close(self) -> None:
        self.session.close()

    def __enter__(self) -> Self:
        return self

    def __exit__(self, *_exc: object) -> None:
        self.close()

async def observe(self, thread_name: str, session_id: str, *, defer_busy: bool=False, read_cursor: Callable[..., Awaitable[CurrentNativeCursor | None]]=NativeSourceCursor.read_async) -> CursorEnvelope:
    if self.root_id is None:
        raise ValueError('Native cursor requires the configured root')
    revision = self.delivery(session_id).next_revision()
    scope = self.scope(thread_name, session_id)
    unavailable = CursorEnvelope(scope, revision, UnavailableCursorObservation())
    if scope is None:
        return unavailable
    try:
        bus = MessageBus(self.comms.root / 'bus.jsonl', self.comms.registry, private_response_writes=True)
        cursor = await read_cursor(bus, wire_root_id=self.root_id, owner_name=thread_name)
    except BlockingIOError:
        current = self.scope(thread_name, session_id)
        if defer_busy and current == scope:
            raise
        return CursorEnvelope(current, revision, UnavailableCursorObservation())
    except (OSError, ValueError, sqlite3.Error, CoordinationError, KeyError):
        current = self.scope(thread_name, session_id)
        return CursorEnvelope(current, revision, UnavailableCursorObservation())
    current = self.scope(thread_name, session_id)
    if current != scope:
        return CursorEnvelope(current, revision, UnavailableCursorObservation())
    return CursorEnvelope(scope, revision, EmptyCursorObservation() if cursor is None else VerifiedCursorObservation(cursor))

def observe(self, text: str | None, session: TurnSession) -> McpLiveReceipt | None:
    if self.receipt is not None or not session.permits_live_receipt():
        return None
    self.receipt = McpLiveReceipt.from_status(text, session.original_input_id)
    return self.receipt

def observe(self, owner_created_at: float, current: Goal | None) -> None:
    """Reconcile uncertain writes and label unjournaled changes truthfully."""
    for row in self._rows(owner_created_at):
        if row.state != 'pending':
            continue
        if current == row.after:
            self._sync_visible_registry()
            self._set_state(row.sequence, 'committed')
        elif current == row.before:
            self._set_state(row.sequence, 'aborted')
        else:
            self._set_state(row.sequence, 'uncertain')
    committed = [row for row in self._rows(owner_created_at) if row.state == 'committed']
    if not committed:
        if current is not None:
            self._insert(owner_created_at, 'baseline', 'committed', None, current)
        return
    last = committed[-1].after
    if last != current:
        self._insert(owner_created_at, 'observed_gap', 'committed', last, current)

class InputDrain(FutureInputQueue):

    def __init__(self, comms: Comms, sessions: SessionLifecycle, runtime: RuntimeServer, effects: InputEffects, auto_wake: bool):
        self.comms = comms
        self.sessions = sessions
        self.runtime = runtime
        self.effects = effects
        self.drain_tasks: dict[str, asyncio.Task[None]] = {}
        self.backend_inboxes: dict[str, asyncio.Queue[str | dict[str, Any]]] = {}
        self.queued_inputs: dict[str, dict[str, QueuedInput]] = {}
        self.restored_inputs: dict[str, dict[str, QueuedInput]] = {}
        self.queue_revisions: dict[str, int] = {}
        self.following_sources: dict[str, dict[str, AcceptedFollowingInput]] = {}
        self.turn_input_keys: dict[str, set[str]] = {}
        self.original_sources: dict[str, OriginalTurnInput] = {}
        self.selected_summary_admissions: dict[str, SelectedSummaryAdmission] = {}
        self.dispositions = InputDispositions(comms.root / InputDispositions.filename)
        self.auto_wake = auto_wake
        self.pending_turns: dict[str, list[ScheduledTurn]] = {}
        self.drain_locks: dict[str, asyncio.Lock] = {}
        self.closing = False
        self.wake_tasks: dict[str, asyncio.Task[None]] = {}
        self._idle_private_revisions: dict[str, tuple] = {}

    async def clear_queued_inputs(self, session_id: str) -> None:
        """Drop prompts queued against the backend for this session.

        Pi's own queue is cleared, then the local deferred-display list is
        reset. Callers may re-send the prompts they want to keep.
        """
        with _store_lock(self.comms._wire_lock_path):
            inbox = self.backend_inboxes.get(session_id)
            if inbox is not None:
                inbox.put_nowait({'type': 'clear_queue'})
            self.queued_inputs[session_id] = {key: retained for key, item in self.queued_inputs.get(session_id, {}).items() if (retained := item.after_clear()) is not None}
            self.restored_inputs.pop(session_id, None)
        await self.emit_queue_state(session_id)

    def queue_binding(self, session_id: str) -> QueueScope | None:
        try:
            owner, admission = self.comms.registry.live_owner_with_admission(self.sessions.bindings.get(session_id, session_id))
        except (OSError, ValueError):
            return None
        return QueueScope(session_id, AdmissionIdentity(owner.incarnation, admission), owner.pid)

    def queue_state(self, session_id: str) -> QueueChangedUpdate:
        """The producer owns the complete exact-ID queue projection."""
        revision = self.queue_revisions.get(session_id, 0) + 1
        self.queue_revisions[session_id] = revision
        scope = self.queue_binding(session_id)
        if scope is None:
            return QueueChangedUpdate(None, revision, UnavailableQueueProjection())

        def current(values: dict[str, QueuedInput]) -> tuple[QueueItem, ...]:
            return tuple((QueueItem(input_id, item.text) for input_id, item in values.items() if item.context.owns(scope.admission)))
        items = current(self.queued_inputs.get(session_id, {}))
        restored = current(self.restored_inputs.get(session_id, {}))
        rows = items + restored
        try:
            sizes = [len(row.text.encode('utf-8')) for row in rows]
        except (AttributeError, UnicodeError):
            return QueueChangedUpdate(scope, revision, UnavailableQueueProjection())
        if len(rows) > 32 or any((size > 4096 for size in sizes)) or sum(sizes) > 65536:
            return QueueChangedUpdate(scope, revision, UnavailableQueueProjection())
        return QueueChangedUpdate(scope, revision, AvailableQueueProjection(items, restored))

    async def emit_queue_state(self, session_id: str, *, client: Any=None) -> None:
        await (client or self.runtime).session_update(session_id=session_id, update=AgentMessageChunk(session_update='agent_message_chunk', content=TextContentBlock(type='text', text=''), field_meta=encode_updates(self.queue_state(session_id))))

    async def emit_input_started(self, session_id: str, text: str | None, input_id: str | None=None, source_scope: QueueScope | None=None, *, native_id: str | None, client: Any=None) -> None:
        scope = self.queue_binding(session_id)
        if source_scope is None or scope is None or (not source_scope.relation(scope).current):
            scope = None
        revision = None
        if scope is not None:
            revision = self.queue_revisions.get(session_id, 0) + 1
            self.queue_revisions[session_id] = revision
        await (client or self.runtime).session_update(session_id=session_id, update=AgentMessageChunk(session_update='agent_message_chunk', content=TextContentBlock(type='text', text=''), field_meta=encode_updates(InputStartedUpdate(input_id, text, scope, revision, native_id))))

    async def emit_input_disposition(self, session_id: str, row: InputAttempt, client: Any=None) -> None:
        await self.emit_input_delivery_changed(session_id, input_id=row.public_id, client=client)

    async def emit_input_delivery_changed(self, session_id: str, *, input_id: str | None=None, client: Any=None) -> None:
        await (client or self.runtime).session_update(session_id=session_id, update=AgentMessageChunk(session_update='agent_message_chunk', content=TextContentBlock(type='text', text=''), field_meta=encode_updates(InputDeliveryChangedUpdate(input_id))))

    async def replay_unknown_inputs(self, session_id: str, client: Any=None) -> None:
        """Refresh the producer-owned delivery ledger; this never replays an input."""
        await self.emit_input_delivery_changed(session_id, client=client)

    def awaiting_input_keys(self, session_id: str) -> frozenset[str] | None:
        """Derive delivery notices from existing owner queues; never create new authority."""
        owner = self.comms.registry.require(self.sessions.require(session_id))
        if owner.pid != os.getpid() or not self.comms.registry.status(owner.name).running:
            return None
        keys = set(self.turn_input_keys.get(session_id, ()))
        keys.update((self.dispositions.bus_key(turn.origin, owner) for turn in self.pending_turns.get(session_id, ()) if turn.origin is not None))
        return frozenset(keys)

    def ensure_live_drain(self, session_id: str) -> None:
        """Keep one background task per session pushing inbox messages live."""
        if self.closing:
            return
        if session_id in self.drain_tasks and (not self.drain_tasks[session_id].done()):
            return
        self.drain_tasks[session_id] = self.runtime.background(self.observe(session_id))

    async def observe(self, session_id: str) -> None:
        next_goal_wait_check = 0.0
        async with aclosing(WireWatch.observations(self.comms.root)) as observations:
            async for _ in observations:
                thread = self.sessions.require(session_id)
                owner = self.comms.registry.snapshot().owner_identity(thread)
                try:
                    await self.drain_inbox(session_id)
                    await self.sessions.config.sync_thread(session_id)
                    if time.monotonic() >= next_goal_wait_check:
                        self.comms.goals.recover_closed_goal_wait(session_id)
                        next_goal_wait_check = time.monotonic() + GOAL_WAIT_RECHECK_INTERVAL
                    self.effects.turns.goals.schedule_goal(session_id)
                    await self.sessions.config.refresh_auth_models()
                except asyncio.CancelledError:
                    raise
                except (OSError, ValueError, sqlite3.Error, CoordinationError, RequestError) as error:
                    self.comms.agents.set_drain_diagnostic(thread, owner, UnavailableDrainDiagnostic(owner, type(error).__name__, str(error)))
                except Exception as error:
                    self.comms.agents.set_drain_diagnostic(thread, owner, StoppedDrainDiagnostic(owner, type(error).__name__, str(error)))
                    raise
                else:
                    if not self.comms.registry.require(thread).executing and session_id not in self.effects.turns.turn_tasks and (session_id not in self.backend_inboxes):
                        self.comms.agents.set_drain_diagnostic(thread, owner, None)

    async def drain_inbox(self, session_id: str) -> int:
        """Push undelivered messages to the client; returns count pushed."""
        async with self.drain_locks.setdefault(session_id, asyncio.Lock()):
            return await self.drain_owned_inbox(session_id)

    def _private_observation_revision(self, session_id: str, root_id: str, wire: tuple, store: Coordination) -> tuple:
        """Original owner/work observations, never delivery or replay authority.

        Other owners' registry phases and SQL writes cannot change this owner's
        observation. Committed wire messages, own pending/recovered work and
        physical replacement still can. Silent context records consume bytes,
        not the message cut used to select delivery.
        """
        registry = self.comms.registry.snapshot()
        thread = registry.require(self.sessions.require(session_id))
        owner = RegistryOwner(thread=thread, admission_generation=registry.admission_generations[thread.name])
        with store.session.read():
            participant = store.participants.get(stable_thread_lookup(owner.thread.created_at))
            pending = next_sealed_assignment(store, participant.lookup, owner.thread.name, after_seq=wire[-1])
            cursor = CursorOwner(thread=owner.thread, admission_generation=owner.admission_generation, wire_root_id=root_id, generation=participant.participant_generation).cursor(store.session._connection)
            original = store.session.path.stat()
        return (root_id, self.effects._private_nk_native_package, self.auto_wake, self.sessions.runtime_enabled, self.sessions.bindings.get(session_id), session_id in self.backend_inboxes, self.effects.turns.turn_state(session_id).busy, session_id in self.effects.turns.turn_tasks, wire, owner, registry.statuses[thread.name], participant, pending, cursor, (original.st_dev, original.st_ino))

    async def _observe_private_revision(self, session_id: str, root_id: str) -> tuple:

        def wire_revision(source):
            if source.marker.root_id != root_id:
                raise IdentityConflict('private drain original root changed')
            return (source.witness.source_identity, source.committed_sequence(), source.marker.admission_after_seq)
        wire = await self.comms.bus.log.read_certified_async(wire_revision)
        return await Coordination.run_async(self.comms.root / 'coordination.sqlite3', partial(self._private_observation_revision, session_id, root_id, wire))

    async def _drain_private_if_changed(self, session_id: str, root_id: str) -> int:
        before = await self._observe_private_revision(session_id, root_id)
        if self._idle_private_revisions.get(session_id) == before:
            await self.effects.cursors.refresh(session_id, self.sessions.require(session_id))
            return 0
        self._idle_private_revisions.pop(session_id, None)
        result = await self.effects._drain_private_nk(session_id, root_id)
        if result == 0 and before == await self._observe_private_revision(session_id, root_id):
            self._idle_private_revisions[session_id] = before
        return result

    async def drain_owned_inbox(self, session_id: str) -> int:
        private_root = self.effects._private_nk_marker()
        pushed = await self._drain_private_if_changed(session_id, private_root)
        WakeScheduleCheck(session_id=session_id, inputs=self).schedule()
        return pushed

    @property
    def background_wakes_disabled(self) -> bool:
        return not self.auto_wake or not self.sessions.runtime_enabled

    async def drain_count(self, session_id: str) -> int:
        return await self.drain_inbox(session_id)

    def pending_followups(self, session_id: str) -> int:
        rows = self.dispositions.read()
        return sum((not rows.all_started(source.keys) for source in self.following_sources.get(session_id, {}).values()))

    async def accept_followup(self, session_id: str, *, text: str, display_text: str, request: PromptRequest, images: tuple[Any, ...]) -> PromptResponse:
        inbox = self.backend_inboxes[session_id]
        with _store_lock(self.comms._wire_lock_path):
            if self.pending_followups(session_id) >= 32:
                raise RequestError.invalid_params({'reason': 'Too many follow-up inputs awaiting their own user start.'})
            controller = self.runtime.controller.get()
            if controller is UNBOUND_CONTROLLER:
                controller = self.sessions.client
            followup = UserFollowupSegment.capture(text.removeprefix(AGENT_PREFIX))
            item, owner = QueuedInput.capture(self, self.sessions.require(session_id), text=display_text, prompt=TurnContext.render_segments((followup,), images=images).text, echo=request.defer_display, images=images, controller=controller, input_id=request.input_id, origin=request.origin)
            source = self.dispositions.read().rows[item.key]
            item = request.accepted(item, source, owner)
            followup = replace(followup, provenance=(*followup.provenance, source.context_provenance()))
            rendered = TurnContext.render_segments((followup,), images=images)
            self.following_sources.setdefault(session_id, {})[item.input_id] = item.source()
            self.turn_input_keys.setdefault(session_id, set()).add(item.key)
            self.queued_inputs.setdefault(session_id, {})[item.input_id] = item
            inbox.put_nowait({'type': 'prompt', 'message': item.prompt, 'contextContributions': FieldCodec.encode(rendered.contributions), 'streamingBehavior': 'steer', '_input_id': item.input_id, **({'images': [image.to_rpc() for image in images]} if images else {})})
            request.enqueue_control(inbox, item.input_id)
        await request.publish_acceptance(self, session_id)
        return PromptResponse(stop_reason='end_turn', field_meta=encode_updates(InputDeliveryChangedUpdate(item.input_id)))

    def bind_native_turn(self, session_id: str, owner: Thread, admission: int, turn_id: str) -> asyncio.Queue[str | dict[str, Any]]:
        """Transfer existing live inputs to the new lease, never read them from disk."""
        inbox = self.backend_inboxes.setdefault(session_id, asyncio.Queue())
        for input_id, item in self.queued_inputs.get(session_id, {}).items():
            self.queued_inputs[session_id][input_id] = item.bind_turn(owner, admission, turn_id)
        return inbox

    def future_inputs(self, owner: Thread, pending_input_keys: tuple[str, ...]) -> dict[str, InputAttempt]:
        """Live queued receipts only; durable UNKNOWN alone never grants this exception.

        The bridge holds the wire lock while reading this owner. Acceptance,
        clear and promotion use that same lock, including their in-memory edits.
        No receipt survives a process restart or an owner/turn change.
        """
        if not pending_input_keys:
            return {}
        if owner.pid != os.getpid() or owner.active_turn is None or self.closing:
            return {}
        result = {}
        for session_id, original in self.original_sources.items():
            if original.compaction_keys(owner.session_file) != pending_input_keys or self.sessions.bindings.get(session_id) != owner.name:
                continue
            for input_id, item in self.queued_inputs.get(session_id, {}).items():
                receipt = item.future_receipt(owner)
                if receipt is not None:
                    result[item.key] = receipt
        return result

    def send_now(self, session_id: str) -> None:
        with _store_lock(self.comms._wire_lock_path):
            inbox = self.backend_inboxes.get(session_id)
            queued = self.queued_inputs.get(session_id, {})
            if inbox is not None and queued:
                for key, item in tuple(queued.items()):
                    queued[key] = item.immediate()
                inbox.put_nowait({'type': 'interrupt_steering', '_input_ids': list(queued)})

    async def stop_wakes(self) -> None:
        self.closing = True
        for task in self.wake_tasks.values():
            task.cancel()
        await asyncio.gather(*self.wake_tasks.values(), return_exceptions=True)
        self.wake_tasks.clear()

    async def close(self) -> None:
        tasks = tuple(self.drain_tasks.values())
        self.drain_tasks.clear()
        self._idle_private_revisions.clear()
        for task in tasks:
            task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)

    async def input_started(self, session_id: str, input_id: str | None, source_scope: QueueScope) -> None:
        original = self.original_sources[session_id]
        input_id = input_id if input_id is not None else original.accepted_id
        source = self.following_sources.get(session_id, {}).get(input_id)
        started_keys = original.keys if input_id is None else source.keys if source else ()
        for key in started_keys:
            row = self.dispositions.read().rows.get(key)
            if row is not None and (not row.unresolved):
                await self.emit_input_disposition(session_id, row)
        row = self.dispositions.read().lookup(started_keys[0] if len(started_keys) == 1 else None)
        if input_id is None and original.notice_keys:
            row = self.dispositions.read().lookup(original.notice_keys[0])
        row = row.require_started(source_scope.admission_generation)
        if input_id is None and original.notice_keys:
            input_id = row.public_id
        item = self.queued_inputs.get(session_id, {}).get(input_id or '')
        text = item.text if item else original.notice_text if input_id == row.public_id else None
        await self.emit_input_started(session_id, text, input_id, source_scope=source_scope, native_id=row.native_id)
        self.queued_inputs.get(session_id, {}).pop(input_id or '', None)
        await self.emit_queue_state(session_id)

    async def input_refused(self, session_id: str, input_id: str | None) -> None:
        if input_id is None:
            return
        source = self.following_sources.get(session_id, {}).pop(input_id, None)
        if source is not None:
            self.turn_input_keys.get(session_id, set()).difference_update(source.keys)
            await self.emit_input_delivery_changed(session_id)
        if self.queued_inputs.get(session_id, {}).pop(input_id, None):
            await self.emit_queue_state(session_id)

    def continue_in_project(self, session_id: str, terminal: Done, original_project: str, current_project: str) -> None:
        if self.closing or current_project == original_project:
            return
        if (continuation := terminal.project_continuation(current_project)):
            self.pending_turns.setdefault(session_id, []).append(continuation)

    async def finish_turn_inputs(self, session_id: str, inbox: asyncio.Queue[str | dict[str, Any]]) -> None:
        """Retire this turn's live capabilities; retain UNKNOWN only as notices."""
        if self.backend_inboxes.get(session_id) is inbox:
            self.backend_inboxes.pop(session_id, None)
        while not inbox.empty():
            pending = inbox.get_nowait()
            if isinstance(pending, str):
                self.pending_turns.setdefault(session_id, []).append(ScheduledTurn(pending))
        with _store_lock(self.comms._wire_lock_path):
            original = self.original_sources.pop(session_id, None)
            self.dispositions.settle_unbound(original.notice_keys if original else ())
        self.following_sources.pop(session_id, None)
        self.turn_input_keys.pop(session_id, None)
        admission = self.selected_summary_admissions.pop(session_id, None)
        if admission is not None:
            admission.invalidate()
        await self.emit_input_delivery_changed(session_id)
        remaining = self.queued_inputs.pop(session_id, {})
        if remaining:
            self.restored_inputs.setdefault(session_id, {}).update({key: restored for key, item in remaining.items() if (restored := item.restore_after_turn()) is not None})
            await self.emit_queue_state(session_id)

    async def run_owned_input(self, session_id: str, thread_name: str, task: str, *, images: tuple[Any, ...]=(), display_text: str | None=None, input_id: str | None=None, origin: InputOrigin=UnattributedInputOrigin()) -> None:
        with _store_lock(self.comms._wire_lock_path):
            item, _owner = InitialInput.capture(self, thread_name, text=display_text or task, prompt=task, echo=display_text is not None, images=images, controller=self.runtime.controller.get(), input_id=input_id, origin=origin)
            self.queued_inputs.setdefault(session_id, {})[item.input_id] = item
        try:
            await self.emit_input_disposition(session_id, self.dispositions.read().lookup(item.key))
            await self.emit_queue_state(session_id)
            await item.dispatch(self.effects.turns, session_id, thread_name)
        finally:
            queued = self.queued_inputs.get(session_id, {})
            if queued.get(item.input_id) is item:
                queued.pop(item.input_id)
                await self.emit_queue_state(session_id)

async def _observe_private_revision(self, session_id: str, root_id: str) -> tuple:

    def wire_revision(source):
        if source.marker.root_id != root_id:
            raise IdentityConflict('private drain original root changed')
        return (source.witness.source_identity, source.committed_sequence(), source.marker.admission_after_seq)
    wire = await self.comms.bus.log.read_certified_async(wire_revision)
    return await Coordination.run_async(self.comms.root / 'coordination.sqlite3', partial(self._private_observation_revision, session_id, root_id, wire))

def observe(self):
    from .native_pi import NativePiUnavailable, _private_session_dir
    try:
        _private_session_dir(self.source.path.parent)
        appended = tuple(self.decode_rows(self.source.rows()))
        entries = self.entries + appended
        if not entries or not isinstance(entries[0], SessionEntry):
            raise ValueError('Native Pi session header is invalid')
        entries[0].require_header()
        _private_session_dir(self.source.path.parent)
    except NativePiUnavailable:
        self.close()
        raise
    except (ValueError, TypeError, KeyError) as error:
        self.close()
        raise NativePiUnavailable(f'Native Pi session evidence is invalid: {error}') from error
    self.entries = entries
    return (entries[0], entries)

@classmethod
def observe(cls, session_file: str | None) -> SessionObservation:
    if not isinstance(session_file, str) or not session_file:
        return UnavailableSessionObservation(ValueError('No selected native session'))
    try:
        native = FileRevision.from_stat(Path(session_file).stat())
        try:
            proof = PresentInputProofRevision(FileRevision.from_stat(Path(session_file + '.input-proof').stat()))
        except FileNotFoundError:
            proof = MissingInputProofRevision()
        return cls(native, proof)
    except OSError as error:
        return UnavailableSessionObservation(error)

@dataclass(slots=True)
class StoreLockContention:
    """One operation's borrowed wait resource, spent only at physical locks.

    Source reading, decoding and consumer work cannot spend this resource.
    It grants no owner, input, proof or replay permission.
    """
    remaining: float

    def waits(self, descriptor: int, platform: Platform, *, shared: bool) -> Iterator[float]:
        """One physical acquisition algorithm; drivers own sync/async waiting."""
        while True:
            begun = time.monotonic()
            try:
                platform.try_store_lock(descriptor, shared=shared)
            except BlockingIOError:
                self.remaining -= time.monotonic() - begun
                if self.remaining <= 0:
                    raise
                begun = time.monotonic()
                try:
                    yield min(self.remaining, platform.store_lock_interval)
                finally:
                    self.remaining -= time.monotonic() - begun
            else:
                return

    def acquire(self, descriptor: int, platform: Platform, *, shared: bool) -> None:
        for delay in self.waits(descriptor, platform, shared=shared):
            time.sleep(delay)

    async def acquire_async(self, descriptor: int, platform: Platform, *, shared: bool) -> None:
        for delay in self.waits(descriptor, platform, shared=shared):
            await asyncio.sleep(delay)

@dataclass(frozen=True)
class StoreLock:
    """One physical lock's descriptor and opened durability resource."""
    descriptor: int
    source: CertifiedSourceRead | None

    def certified_read(self) -> CertifiedSourceRead:
        if self.source is None:
            raise RelationViolationError('Store has no certified original wire source.')
        return self.source

@contextmanager
def _store_lock(store_path: Path, *, blocking: bool=True, max_bus_bytes: int | None=None, shared: bool=False, contention: StoreLockContention | None=None) -> Iterator[StoreLock]:
    """Canonical synchronous acquisition; inherited POSIX custody ends at last close."""
    from .child_process import Platform
    platform = Platform.current()
    with _store_lock_file(store_path) as lock_file:
        if contention is None:
            platform.acquire_store_lock(lock_file.fileno(), shared=shared, blocking=blocking)
        else:
            contention.acquire(lock_file.fileno(), platform, shared=shared)
        with _held_store_source(store_path, lock_file, platform, max_bus_bytes) as lock:
            yield lock

async def acquire_async(self, descriptor: int, platform: Platform, *, shared: bool) -> None:
    for delay in self.waits(descriptor, platform, shared=shared):
        await asyncio.sleep(delay)

def certified_read(self) -> CertifiedSourceRead:
    if self.source is None:
        raise RelationViolationError('Store has no certified original wire source.')
    return self.source

def observe(self, tokens: int) -> None:
    self.used = tokens
    self.provisional = True

async def observe(self, event: PiEvent, session: TurnSession) -> AsyncIterator[events.AgentEvent]:
    self.tick()
    if self.retry_recovery_pending and event.retry_progress:
        self.retry_recovery_pending = False
        yield self.state('recovered', self.retry_recovery_reason, 0, phase=phases.ModelWaitPhase())
    if event.accepts_prompt:
        self.prompt_accepted = True
        if event.invalidates_stop:
            session.output.final_assistant_stop = False
        self.progress()
        if not session.active_tools:
            self.phase = self.phase.model_progress()

class WireLog:

    def __init__(self, path: Path):
        self.path = Path(path)

    @contextmanager
    def locked(self, *, blocking: bool=True, max_bus_bytes: int | None=None, contention: StoreLockContention | None=None):
        """The existing canonical bus lock and durability read barrier."""
        with _store_lock(self.path, blocking=blocking, max_bus_bytes=max_bus_bytes, contention=contention) as lock:
            yield lock

    @contextmanager
    def certified_read(self, *, blocking: bool=True, contention: StoreLockContention | None=None):
        """Borrow the original source verified by this canonical lock barrier."""
        with _store_lock(self.path, blocking=blocking, contention=contention) as lock:
            with self._certified_source(lock) as source:
                yield source

    async def read_certified_async(self, read: Callable):
        """Acquire cancellably, then consume the whole source in its worker.

        Return detached observations only. Verification and the callback share
        one resource thread; no SQLite connection crosses to the event loop.
        Cancellation joins acquired work before the original descriptor closes.
        """
        from .child_process import Platform
        from .coordinator import Coordination
        platform = Platform.current()
        with _store_lock_file(self.path) as lock_file:
            await StoreLockContention(math.inf).acquire_async(lock_file.fileno(), platform, shared=False)
            return await Coordination.run_worker(partial(self._read_certified, lock_file, platform, read))

    def _read_certified(self, lock_file, platform, read):
        with _held_store_source(self.path, lock_file, platform, None) as lock:
            with self._certified_source(lock) as source:
                return read(source)

    @contextmanager
    def _certified_source(self, lock: StoreLock):
        """Sync and async acquisition consume the same marker/currentness owner."""
        marker = self._private_marker_unlocked()
        source = lock.certified_read()
        source.require_marker(marker)
        yield source
        source.require_current()

    def conversation_sources(self, lookup, predicate, parameters, *, limit, ascending):
        """Read an original window through its existing canonical barrier."""
        with _store_lock(self.path) as lock:
            if not self.path.exists():
                return ()
            marker = self._private_marker_unlocked()
            source = lock.certified_read()
            source.require_marker(marker)
            originals = source.conversation_sources(lookup, predicate, parameters, limit=limit, ascending=ascending)
            source.require_current()
        return tuple(originals)

    def addressed_sources(self, lookup: str, after_seq: int=0) -> Iterator[CommittedDelivery]:
        """Borrow bounded pages from one original committed append-only cut.

        A later append cannot extend this iteration. Each page captures exact
        original pointers and bytes inside certification; validation and all
        consumer work occur after its publication custody has closed.
        """
        request = AddressedPage(lookup=lookup, after_seq=after_seq)
        with self.certified_read() as source:
            witness, captured, more = source.addressed_page(self, request)
        while True:
            originals = tuple(captured)
            yield from originals
            if not more:
                return
            request = replace(request, after_seq=originals[-1].message.seq)
            with self.certified_read() as source:
                _, captured, more = source.addressed_page(self, request, prefix=witness)

    def full_history(self) -> list[Message]:
        with self.verified_snapshot() as records:
            return [message for record in records for message in record.messages()]

    @contextmanager
    def delivery_snapshot(self):
        """Original routing members derive from the same opened strict read."""
        with self.verified_snapshot() as records:
            yield (item for record in records for item in record.delivery_messages())

    def record_context(self, manifest) -> None:
        """Append one text-free observation through the original sealed writer."""
        from .wire_record import ContextManifestWireObservation, ObservationWireRecord
        with self.locked():
            marker = self._private_marker_unlocked()
            record = ObservationWireRecord(ContextManifestWireObservation(manifest))
            self._append_private_unlocked(marker, record.to_wire())

    def context_manifests(self, name: str, registry):
        """Capture original source and rename membership before decoding.

        The original wire -> bus -> registry order selects the read snapshot;
        neither physical publication lock survives into its decoder.
        """
        with _store_lock(self.path.parent / 'wire'):
            with self.certified_read() as source:
                snapshot = registry.snapshot()
                incarnation = snapshot.require(name).incarnation
                captured = source.context_manifests(incarnation, snapshot)
        return tuple(captured)

    def retained_task_facts_unlocked(self, recipient: ThreadIncarnation):
        """Capture exact task facts from their original addressed declarations.

        Caller owns the original bus lock. Outgoing declared decisions belong
        to their author's source too; unrelated messages cannot invalidate it.
        """
        marker = self._private_marker_unlocked()
        return self._retained_task_facts(self.verified_records_unlocked(marker), recipient)

    @staticmethod
    def _retained_task_facts(records, recipient: ThreadIncarnation):
        facts = []
        lookup = stable_thread_lookup(recipient.created_at)
        for record in records:
            for message in record.compaction_messages_for(lookup):
                facts.extend(message.retained_task_facts())
        return tuple(facts)

    @contextmanager
    def retained_sources(self, name: str, registry):
        """Borrow one certified wire/registry/input cut for retained readers.

        Capture under the existing wire boundary, then decode outside it. The
        acquired wire prefix remains certified for the entire consumer scope.
        """
        from .exporting import WireExportBoundary
        from .input_disposition import InputDispositions
        from .retained_task_facts import RetainedTaskFacts
        with ExitStack() as resources:
            with _store_lock(self.path.parent / 'wire'):
                snapshot = registry.snapshot()
                owner = snapshot.require(name)
                inputs = InputDispositions(self.path.parent / InputDispositions.filename).read()
                metadata, _, stream, boundary, _ = resources.enter_context(self._opened_wire_snapshot(need_sequence=False))
                export = WireExportBoundary(metadata.last_seq, time.time())
            facts = self._retained_task_facts(self._snapshot_records(metadata, stream, boundary), owner.incarnation)
            yield (owner, snapshot, RetainedTaskFacts(facts), inputs, export)

    def retained_context(self, name: str, registry):
        """Authored retained context; also the source of instruction export.

        This deliberately excludes unpinned inputs, goals and native artifacts.
        CompactionBoundary inspection owns those separate observation scopes.
        """
        from .retained_context import RetainedSegment
        from .retained_task_facts import RetainedTaskFacts
        with self.retained_sources(name, registry) as (owner, snapshot, facts, inputs, export):
            retained = RetainedTaskFacts((*facts.facts, *facts.original_input_facts(inputs)))
            return RetainedSegment.capture(retained.for_owner(owner, snapshot), owner, snapshot, export)

    def _assert_private_directory(self) -> None:
        """Require a nonredirectable, owned ancestry (root sticky /tmp permitted)."""
        if os.name != 'posix':
            raise RelationViolationError('Private bus requires POSIX ownership and modes.')
        if '..' in self.path.parts:
            raise RelationViolationError('Private bus directory ancestry is not trusted.')
        path = self.path.parent.absolute()
        while True:
            info = path.lstat()
            sticky_root = info.st_uid == 0 and bool(info.st_mode & stat.S_ISVTX)
            if not stat.S_ISDIR(info.st_mode) or info.st_uid not in {0, os.geteuid()} or (info.st_mode & 18 and (not sticky_root)):
                raise RelationViolationError('Private bus directory ancestry is not trusted.')
            if path == path.parent:
                break
            path = path.parent

    def _claim_projection_unlocked(self, metadata: WireMetadata) -> tuple[ClaimProjection, int]:
        """Project claims and return the verified bus high-water in one scan."""
        return self._claim_projection(self.verified_records_unlocked(metadata))

    @staticmethod
    def _claim_projection(records) -> tuple[ClaimProjection, int]:
        projection = ClaimProjection()
        verified_sequence = 0
        for record in records:
            verified_sequence = record.sequence_after(verified_sequence)
            for previous in record.messages():
                if previous.claim_transition is not None:
                    projection = apply_transition(projection, previous.claim_transition)
        return (projection, verified_sequence)

    def claim_projection(self) -> ClaimProjection:
        """Derive ownership exclusively from guarded, verified bus envelopes."""
        with self._opened_wire_snapshot(need_sequence=False) as (metadata, _, stream, boundary, _):
            if not metadata.claims:
                raise RelationViolationError('Claim read barrier is unavailable.')
            projection, _verified_sequence = self._claim_projection(self._snapshot_records(metadata, stream, boundary))
            return projection

    def _private_marker_unlocked(self) -> WireMetadata:
        self._assert_private_directory()
        if self.path.parent.lstat().st_uid != os.geteuid():
            raise RelationViolationError('Private bus directory is not owner-controlled.')
        sequence_path = self.metadata_path
        repair_path = self.path.with_name(self.path.name + '.corrupt')
        for path in (sequence_path, self.path, repair_path):
            if not path.exists() and (not path.is_symlink()):
                continue
            info = path.lstat()
            if not stat.S_ISREG(info.st_mode) or info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 384:
                raise RelationViolationError('Private bus files require regular owner-only mode.')
        if not sequence_path.exists():
            raise RelationViolationError('Private bus writer has no durable protocol marker.')
        metadata = self.read_metadata_unlocked(required=True)
        if not metadata.private:
            raise RelationViolationError('Private bus writer has no durable protocol marker.')
        return metadata

    def verified_records_unlocked(self, metadata: WireMetadata, *, on_row: Callable[[int, bytes, WireRecord], None] | None=None) -> Iterator[WireRecord]:
        """Entire strict stream; later corruption cannot certify an earlier append."""
        scan = WireScan(metadata)
        if not self.path.exists():
            return
        with self.path.open('rb') as stream:
            while True:
                offset = stream.tell()
                line = stream.readline(scan.max_row_bytes + 1)
                if not line:
                    break
                record = scan.read(line)
                if on_row is not None:
                    on_row(offset, line, record)
                yield record

    def _append_private_unlocked(self, metadata: WireMetadata, row: Mapping[str, object]) -> None:
        """Durably reserve a sequence, append one row, then sync its parent.

        A failed append or bus parent sync leaves the outcome UNKNOWN.
        """
        metadata.access.require_append()
        encoded = json.dumps(row, allow_nan=False).encode('utf-8') + b'\n'
        if len(encoded) > 8 * 1024 * 1024:
            raise RelationViolationError('Private bus row exceeds the byte limit.')
        record = WireRecord.from_wire(row, metadata.root_id)
        metadata.last_seq = record.sequence_after(metadata.last_seq)
        self.write_metadata_unlocked(metadata)
        descriptor = os.open(self.path, os.O_APPEND | os.O_CREAT | os.O_WRONLY | getattr(os, 'O_NOFOLLOW', 0), 384)
        try:
            info = os.fstat(descriptor)
            if not stat.S_ISREG(info.st_mode) or info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 384:
                raise RelationViolationError('Private bus append target is not owner-only.')
            with os.fdopen(descriptor, 'ab', closefd=False) as output:
                output.write(encoded)
                output.flush()
                os.fsync(output.fileno())
        finally:
            os.close(descriptor)
        directory_fd = os.open(self.path.parent, os.O_RDONLY | getattr(os, 'O_DIRECTORY', 0))
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
        from .private_bus_checkpoint import append_private_bus_checkpoint_unlocked, certificate_enabled
        if certificate_enabled(self.path):
            try:
                append_private_bus_checkpoint_unlocked(self, metadata, encoded, record)
            except Exception as error:
                raise RelationViolationError('Private bus checkpoint publication outcome UNKNOWN.') from error

    def read_delivery_cohort(self, wire_root_id: str, wire_seq: int) -> CommittedDelivery:
        """Bus-owned attestation of a committed initial row; no live re-routing."""
        from .audience_manifest import MAX_WIRE_SEQ
        if type(wire_seq) is not int or not 0 < wire_seq <= MAX_WIRE_SEQ:
            raise ValueError('wire_seq must be a positive SQLite-range integer.')
        with self.certified_read() as source:
            if wire_root_id != source.witness.root_id:
                raise RelationViolationError('Initial wire root does not match the bus marker.')
            return source.delivery(wire_seq)

    def delivery_cohorts_unlocked(self, wire_root_id: str, sequences):
        """Borrow canonical checkpoint resources under the caller's bus custody."""
        from .private_bus_checkpoint import opened_private_checkpoint_unlocked
        marker = self._private_marker_unlocked()
        if marker.root_id != wire_root_id:
            raise RelationViolationError('Initial wire root does not match the bus marker.')
        with opened_private_checkpoint_unlocked(self, marker) as source:
            originals = tuple((source.delivery(seq) for seq in sequences))
            source.require_current()
            return originals

    def _keyed_receipt_unlocked(self, intent: PublicationIntents) -> tuple[Message | None, int, WireMetadata]:
        """Resolve the original receipt through the canonical sealed prefix.

        Caller holds the bus file lock. Absence is NOT authorization to append.
        """
        if type(intent) is not PublicationIntents:
            raise TypeError('Keyed response requires a validated PublicationIntents.')
        metadata = self._private_marker_unlocked()
        from .private_bus_checkpoint import opened_private_checkpoint_unlocked
        with opened_private_checkpoint_unlocked(self, metadata) as source:
            matched = source.keyed_receipt(intent)
            source.require_current()
            return (matched, source.witness.through_seq, metadata)

    def read_keyed_response(self, intent: PublicationIntents) -> Message | None:
        """Read-only exact receipt resolution; never append or repair an absent row."""
        with _store_lock(self.path):
            matched, _, _ = self._keyed_receipt_unlocked(intent)
            return matched

    @staticmethod
    def _public_page_records(record: Mapping, raw_size: int, metadata: WireMetadata) -> Iterator[tuple[Message, int]]:
        """Silent facts consume physical bytes, never message/display budgets."""
        for message in WireRecord.public_from_wire(record).messages():
            if has_private_wire_fields(record):
                yield (message, len(json.dumps(message.to_wire()).encode()) + 1)
            else:
                message.require_retained_admission(metadata.admission_after_seq)
                yield (message, raw_size)

    @contextmanager
    def _opened_wire_snapshot(self, *, need_sequence: bool=True):
        """Own one fixed opened inode/byte boundary beyond physical custody."""
        with ExitStack() as resources:
            with _store_lock(self.path) as lock:
                metadata = self._private_marker_unlocked() if self.path.exists() or self.metadata_path.exists() else WireMetadata()
                through = self._committed_sequence_unlocked(lock) if need_sequence else 0
                try:
                    stream = resources.enter_context(self.path.open('rb'))
                except FileNotFoundError:
                    stream = None
                boundary = stream.seek(0, 2) if stream is not None else 0
                if stream is not None:
                    stream.seek(0)
                revision = BusFileRevision.capture(stream) if stream is not None else None
            yield (metadata, through, stream, boundary, revision)

    @contextmanager
    def verified_snapshot(self) -> Iterator[Iterator[WireRecord]]:
        """Run the original strict WireScan after releasing publication custody.

        Uncertified streams retain the same complete validation algorithm.
        This resource is a fixed read, not a current append/admission permit.
        """
        with self._opened_wire_snapshot(need_sequence=False) as (metadata, _, stream, boundary, _):
            yield self._snapshot_records(metadata, stream, boundary)

    @contextmanager
    def projection_snapshot(self):
        """Lend one opened source cut to disposable indexes after bus release.

        The index may seek this stream within its original revision. If index
        acquisition fails, the strict record iterator reads that SAME cut.
        Its stream remains owned here; no projection acquires bus authority.
        """
        with self._opened_wire_snapshot(need_sequence=False) as (metadata, _, stream, boundary, revision):
            yield (metadata, revision, stream, self._snapshot_records(metadata, stream, boundary))

    @staticmethod
    def _snapshot_records(metadata, stream, boundary):
        scan = WireScan(metadata)
        while stream is not None and stream.tell() < boundary:
            raw = stream.readline(min(scan.max_row_bytes + 1, boundary - stream.tell()))
            if not raw:
                break
            yield scan.read(raw)

    @contextmanager
    def _record_snapshot(self, *, need_sequence: bool=True) -> Iterator[tuple[int, Iterator[tuple[Message, int]]]]:
        """Public page accounting borrows the one original opened byte boundary."""
        with self._opened_wire_snapshot(need_sequence=need_sequence) as (metadata, through, stream, boundary, _):
            records = (page_row for record, size in _iter_jsonl_stream(stream, boundary=boundary, label='wire snapshot') for page_row in self._public_page_records(record, size, metadata)) if stream is not None else iter(())
            yield (through, records)

    @contextmanager
    def full_history_snapshot(self) -> Iterator[tuple[int, Iterator[Message]]]:
        """Open one fixed append boundary without retaining the complete wire."""
        with self._record_snapshot() as (through, records):
            yield (through, (message for message, _ in records))

    def message_by_id(self, message_id: str) -> Message | None:
        """Resolve an ID-only request through the canonical opened wire stream.

        Display callers carry original seq/id references and use their bounded
        certified window. There is no second receipt-offset index or cache.
        """
        with self.full_history_snapshot() as (_, messages):
            return next((message for message in messages if message.message_id == message_id), None)

    def messages_for_references(self, references):
        return tuple((source.message for source in self.deliveries_for_references(references)))

    def deliveries_for_references(self, references):
        """One canonical lock/certificate lifetime for a visible source window."""
        if not references:
            return ()
        with self.certified_read() as source:
            originals = source.references(references)
        return tuple(originals)

    def total_messages(self) -> int:
        with self.verified_snapshot() as records:
            return sum((1 for record in records for _ in record.messages()))

    def latest_sequence(self) -> int:
        """Return the global high-water sequence without loading message bodies."""
        with _store_lock(self.path) as lock:
            return self._committed_sequence_unlocked(lock)

    def _iter_log_unlocked(self) -> Iterator[Message]:
        if self.path.exists():
            marker = self._private_marker_unlocked()
            for record in self.verified_records_unlocked(marker):
                yield from record.messages()

    def _committed_sequence_unlocked(self, lock: StoreLock) -> int:
        """Read the committed cut from the resource acquired by this barrier.

        The certificate's global through_seq is not the addressed page's
        latest_source_seq or a marker reservation. Claim streams without an
        installed certificate still require their original strict traversal.
        """
        if lock.source is not None:
            return lock.certified_read().committed_sequence()
        if self.claim_gate_enabled():
            return max((message.seq for message in self._iter_log_unlocked()), default=0)
        return self.read_metadata_unlocked().last_seq

    def claim_gate_enabled(self) -> bool:
        if self.path.name != 'bus.jsonl':
            return False
        metadata = self.read_metadata_unlocked()
        from .private_bus_checkpoint import certificate_enabled
        if certificate_enabled(self.path) and (not metadata.claims):
            raise RelationViolationError('Private checkpoint lacks its claim read barrier.')
        return metadata.claims

    @contextmanager
    def verify_before_read_unlocked(self):
        """Make every visible opt-in bus row durable before ANY bus-lock reader sees it.

        The marker is fsynced before the first claim send. A failed bus append may
        leave a complete, visible row: another cooperating process must fsync the
        opened inode and its directory, then reject incomplete/corrupt rows, before
        treating either the announcement or the claim as committed. This hook is
        entered by the shared bus lock, including ordinary inbox/history readers.
        """
        if not self.claim_gate_enabled():
            yield None
            return
        private_marker = self.read_metadata_unlocked()
        marker = self.metadata_path
        marker_info = marker.lstat()
        if os.name != 'posix' or not stat.S_ISREG(marker_info.st_mode) or marker_info.st_uid != os.geteuid() or (stat.S_IMODE(marker_info.st_mode) != 384):
            raise RelationViolationError('Claim bus read barrier is not durable and private.')
        from .private_bus_checkpoint import opened_claim_source_unlocked
        with opened_claim_source_unlocked(self, private_marker) as source:
            yield source

    @property
    def metadata_path(self) -> Path:
        return self.path.with_name('bus_meta.json')

    def read_metadata_unlocked(self, *, required: bool=False) -> WireMetadata:
        """Read one marker inode under its leaf lock, independently of registry reads.

        Callers still own any required bus/registry transaction. Marker ownership
        is checked on the opened inode before this lock lets publication retire
        it; zero or multiple links are never accepted as owner-only storage.
        """
        with _store_lock(self.metadata_path, shared=True):
            try:
                descriptor = os.open(self.metadata_path, os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0) | getattr(os, 'O_NONBLOCK', 0))
            except FileNotFoundError as error:
                if required or self.metadata_path.is_symlink() or self.path.exists():
                    raise RelationViolationError('Bus protocol marker is missing or redirected.') from error
                return WireMetadata()
            except OSError as error:
                raise RelationViolationError('Bus protocol marker is unreadable or redirected.') from error
            with os.fdopen(descriptor, encoding='utf-8') as source:
                info = os.fstat(source.fileno())
                if not stat.S_ISREG(info.st_mode):
                    raise RelationViolationError('Bus protocol marker must be regular storage.')
                try:
                    data = json.load(source, object_pairs_hook=unique_wire_object)
                except (ValueError, UnicodeError) as error:
                    raise RelationViolationError('Bus protocol marker is malformed.') from error
            try:
                metadata = FieldCodec.decode(WireMetadata, data)
                if FieldCodec.encode(metadata) != data:
                    raise ValueError('Noncanonical bus protocol marker')
            except (TypeError, ValueError) as error:
                raise RelationViolationError(f'Bus protocol marker is invalid: {error}') from error
            if metadata.private and (info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 384 or info.st_nlink != 1):
                raise RelationViolationError('Private bus protocol marker is not owner-only')
            return metadata

    def write_metadata_unlocked(self, metadata: WireMetadata) -> None:
        with _store_lock(self.metadata_path):
            _atomic_write_text(self.metadata_path, json.dumps(FieldCodec.encode(metadata), indent=2), fsync_parent=True)

    def require_fresh_private_root_unlocked(self) -> None:
        self._assert_private_directory()
        root_info = self.path.parent.lstat()
        if root_info.st_uid != os.geteuid() or stat.S_IMODE(root_info.st_mode) != 448:
            raise RelationViolationError('Private bus directory must be owner-only.')
        repair = self.path.with_name(self.path.name + '.corrupt')
        if any((path.exists() or path.is_symlink() for path in (self.metadata_path, self.path, repair))):
            raise RelationViolationError('Existing unmarked bus data is read-only until its history is rewritten into the current source format.')

@contextmanager
def certified_read(self, *, blocking: bool=True, contention: StoreLockContention | None=None):
    """Borrow the original source verified by this canonical lock barrier."""
    with _store_lock(self.path, blocking=blocking, contention=contention) as lock:
        with self._certified_source(lock) as source:
            yield source

def _read_certified(self, lock_file, platform, read):
    with _held_store_source(self.path, lock_file, platform, None) as lock:
        with self._certified_source(lock) as source:
            return read(source)

class WireWatch(ABC):
    """One observation cadence and its resources, including notification loss."""

    @abstractmethod
    async def prepare(self) -> None:
        ...

    @abstractmethod
    async def wait(self) -> WireWatch:
        ...

    def close(self) -> None:
        pass

    @staticmethod
    async def observations(root: Path) -> AsyncIterator[None]:
        watcher = open_wire_watcher(root)
        try:
            while True:
                await watcher.prepare()
                yield None
                watcher = await watcher.wait()
        finally:
            watcher.close()

def observe(self):
    with NativeEntry.open_evidence(Path(self.session.session_file)) as evidence:
        context = NativeContextProof.read_evidence(Path(self.session.session_file), self.input_id, evidence=evidence)
        self.session.require_same_session(NativeSessionIdentity(context.session_id, str(context.session_file)))
        _, entries = evidence.observe()
        user, = (row for row in entries if row.id == context.session_entry_id)
        answer, = (row for row in entries if row.id == self.answer_entry_id)
        if not isinstance(answer, MessageEntry) or not answer.final_reply:
            raise ValueError('Recorded recall answer is not a successful native terminal')
        if answer.parent_id != user.id:
            raise ValueError('Recall requires a direct tool-free answer to its original probe')
        if self.checkpoint is not None:
            checkpoint = self.checkpoint.observe(self.session, evidence)
            if user.parent_id != checkpoint['native_entry_id']:
                raise ValueError('Recorded probe must immediately follow its original checkpoint')
        else:
            checkpoint = {'applicable': False, 'reason': 'No compaction checkpoint declared for this control', 'canonical_availability': {'evaluated': False, 'reason': 'Full-context control has no committed retained envelope'}}
        return {'context': FieldCodec.encode({item.metadata.get('wire_name', item.name): getattr(context, item.name) for item in fields(NativeContextRecord)}), 'session': FieldCodec.encode(self.session), 'prompt': user.message.text, 'answer': FieldCodec.encode(answer), 'answer_text': answer.message.authoritative_text, 'checkpoint': checkpoint, 'canonical_availability': checkpoint['canonical_availability'], 'prompt_scope': 'original native user and assembled-context proof, not final provider payload'}

